const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.toLowerCase().trim().replace(/\s/g,'');
export function partCandidates(lib,text){const term=normalize(text);return Object.values(lib.cards).filter(c=>c.label.split(/[／/、（）()\s]+/).some(alias=>normalize(alias)===term));}
export function renderPartLookup(lib,word,text){
  const candidates=partCandidates(lib,text),roots=word.families.map(fid=>lib.cards['root-'+fid]).filter(Boolean),standalone=Object.hasOwn(lib.words,text)?lib.words[text]:null;
  return`<div class="dialog-body"><button class="close" data-action="close-detail" aria-label="关闭查询">×</button><span class="eyebrow muted">构词线索查询</span><h2 class="detail-word" lang="en">${esc(text)}</h2><p class="muted">出现在 <strong lang="en">${esc(word.word)}</strong> 中 · ${esc(word.pos)} ${esc(word.meaning)}</p><p class="notice mt">${candidates.length>1?'这个拼写有不同作用，先看本词的构词说明，再比较下面的知识卡。':candidates.length?'找到相关知识卡，可以继续查看含义、词性与例词。':'暂未收录这个形式的独立知识卡。它也可能是词干或历史词形，不一定是能自由使用的词缀。'}</p><section class="detail-section"><h3>在这个词里怎样理解</h3><p>${esc(word.explanation)}</p></section>${candidates.length?`<section class="lookup-options"><h3>相关知识卡</h3>${candidates.map(c=>`<button class="lookup-card" data-card="${esc(c.id)}"><strong lang="en">${esc(c.label)}</strong><span>${esc(c.meaning)}</span><small>${esc(c.outputPos)}</small></button>`).join('')}</section>`:''}${standalone&&standalone.id!==word.wordId?`<section class="detail-section"><h3>相关独立词</h3><button class="word-chip" data-word="${esc(standalone.id)}">${esc(standalone.word)} · ${esc(standalone.meaning)}</button></section>`:''}<section class="detail-section"><h3>所属词根</h3><div class="row">${roots.map(c=>`<button class="btn small outline" data-card="${esc(c.id)}">${esc(c.label)} · ${esc(c.meaning)}</button>`).join('')}</div></section></div><div class="dialog-footer"><button class="btn outline" data-action="return-word" data-id="${esc(word.id)}">返回词卡</button></div>`;
}
